<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>الطبقات الجيولوجية للأرض</title>
<style>
  *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

  :root{
    --crust:#c8a96e;
    --mantle:#d4553a;
    --outer-core:#f0a500;
    --inner-core:#ffe066;
    --bg:#0a0e1a;
    --card:#131a2e;
    --text:#e8e8e8;
    --text-muted:#9a9ab0;
    --accent:#5dade2;
  }

  body{
    font-family:'Segoe UI','Tahoma','Arial',sans-serif;
    background:var(--bg);
    color:var(--text);
    line-height:1.8;
    min-height:100vh;
  }

  /* ── Header ── */
  header{
    text-align:center;
    padding:3rem 1.5rem 1.5rem;
    background:linear-gradient(170deg,#0d1b2a 0%,#1b2d4a 40%,#2a4a6b 100%);
    position:relative;
    overflow:hidden;
  }
  header::after{
    content:'';position:absolute;bottom:-2px;left:0;right:0;height:40px;
    background:var(--bg);
    border-radius:50% 50% 0 0 / 100% 100% 0 0;
  }
  header h1{
    font-size:clamp(1.6rem,4.5vw,2.6rem);
    font-weight:700;
    background:linear-gradient(135deg,#5dade2,#a8d8ea);
    -webkit-background-clip:text;
    -webkit-text-fill-color:transparent;
    background-clip:text;
  }
  header p{color:var(--text-muted);margin-top:.4rem;font-size:1rem}

  /* ── SVG Diagram ── */
  .diagram-wrap{
    display:flex;justify-content:center;align-items:center;
    padding:2rem 1rem 1rem;
  }
  .diagram-wrap svg{max-width:420px;width:90vw;height:auto;filter:drop-shadow(0 0 30px rgba(93,173,226,.15))}

  .layer-label{
    font-family:'Segoe UI','Tahoma','Arial',sans-serif;
    font-weight:700;fill:#fff;font-size:13px;
    text-anchor:middle;pointer-events:none;
  }
  .layer-sub{font-size:10px;fill:rgba(255,255,255,.7);font-weight:400}

  /* ── Content Grid ── */
  main{max-width:1100px;margin:0 auto;padding:1.5rem 1.2rem 3rem}

  .cards{
    display:grid;
    grid-template-columns:repeat(auto-fit,minmax(300px,1fr));
    gap:1.5rem;
  }

  .card{
    background:var(--card);
    border-radius:14px;
    border:1px solid rgba(255,255,255,.06);
    padding:2rem 1.8rem;
    transition:transform .25s,box-shadow .25s;
    position:relative;overflow:hidden;
  }
  .card::before{
    content:'';position:absolute;top:0;right:0;left:0;height:4px;
    border-radius:14px 14px 0 0;
  }
  .card:hover{
    transform:translateY(-4px);
    box-shadow:0 8px 32px rgba(0,0,0,.4);
  }

  .card.crust::before  {background:linear-gradient(90deg,var(--crust),#e0c080)}
  .card.mantle::before {background:linear-gradient(90deg,var(--mantle),#e8705a)}
  .card.core::before   {background:linear-gradient(90deg,var(--outer-core),var(--inner-core))}

  .card h2{
    font-size:1.4rem;margin-bottom:.2rem;
    display:flex;align-items:center;gap:.6rem;
  }
  .card .badge{
    display:inline-block;
    font-size:.75rem;font-weight:600;
    padding:.2rem .7rem;border-radius:999px;
    color:#fff;
  }
  .crust .badge  {background:var(--crust)}
  .mantle .badge{background:var(--mantle)}
  .core .badge  {background:var(--outer-core);color:#1a1a1a}

  .card h2 .title-en{font-weight:300;font-size:.95rem;color:var(--text-muted)}

  .card p{color:var(--text-muted);margin-bottom:.7rem;font-size:.95rem}
  .card ul{list-style:none;padding:0;margin:.5rem 0 0}
  .card ul li{
    padding:.35rem 0;border-bottom:1px solid rgba(255,255,255,.04);
    font-size:.9rem;color:var(--text-muted);
