                    for promo in "qrbn":
                        moves.append(move_str(row, col, r1, c) + promo)
                else:
                    moves.append(move_str(row, col, r1, c))
    _gen_pawn_ep_black(board, moves, row, col, ep)


def _gen_pawn_ep_white(board, moves, row, col, ep):
    """Generate en passant capture for a white pawn at (row, col)."""
    if ep == "-":
        return
    # White EP target is on rank 6 (row 2); white pawn must be on rank 4 (row 4)
    ep_r, ep_c = divmod(SQUARE_INDEX[ep], 8)
    if ep_r == 2 and row == 4 and abs(ep_c - col) == 1:
        moves.append(move_str(row, col, ep_r, ep_c))


def _gen_pawn_ep_black(board, moves, row, col, ep):
    """Generate en passant capture for a black pawn at (row, col)."""
    if ep == "-":
        return
    # Black EP target is on rank 3 (row 5); black pawn must be on rank 4 (row 4)
    ep_r, ep_c = divmod(SQUARE_INDEX[ep], 8)
    if ep_r == 5 and row == 4 and abs(ep_c - col) == 1:
        moves.append(move_str(row, col, ep_r, ep_c))


def move_str(r1: int, c1: int, r2: int, c2: int) -> str:
    return _square_name(r1, c1) + _square_name(r2, c2)

# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------
def legal_moves(fen: str) -> list[str]:
    """Return all pseudo-legal moves for the side to move in UCI notation."""
    board, turn, castling, ep = parse_fen(fen)
    return _gen_all(board, turn, castling, ep)


def perft(fen: str, depth: int) -> int:
    """Perft: count leaf nodes at *depth*.  perft(0) == 1."""
    if depth == 0:
        return 1
    if depth == 1:
        return len(legal_moves(fen))

    board, turn, castling, ep = parse_fen(fen)
    opp = "b" if turn == "w" else "w"
    count = 0
    for mv in _gen_all(board, turn, castling, ep):
        nb = _apply_move(board, mv)
        nc = _update_castling_rights(castling, board, mv, turn)
        nep = _update_ep(board, mv, turn)
        count += _perft_board(nb, opp, nc, nep, depth - 1)
    return count


def _perft_board(board, turn, castling, ep, depth: int) -> int:
    if depth == 0:
        return 1
    if depth == 1:
        return len(_gen_all(board, turn, castling, ep))

    count = 0
    opp = "b" if turn == "w" else "w"
    for mv in _gen_all(board, turn, castling, ep):
        nb = _apply_move(board, mv)
        nc = _update_castling_rights(castling, board, mv, turn)
        nep = _update_ep(board, mv, turn)
        count += _perft_board(nb, opp, nc, nep, depth - 1)
    return count


def _gen_all(board, turn, castling="", ep="") -> list[str]:
    moves: list[str] = []
    for r in range(8):
        for c in range(8):
            moves.extend(_gen_piece_moves(board, turn, r, c, ep))
    moves.extend(_gen_castling_moves(board, turn, castling))
    return moves

